def backfill_sla_deadlines(apps, schema_editor):
    Ticket = apps.get_model('helpdesk', 'Ticket')
    Comment = apps.get_model('helpdesk', 'Comment')
    sla_hours = {
        'low': (24, 120),
        'normal': (8, 72),
        'high': (4, 24),
        'critical': (1, 8),
    }
    for ticket in Ticket.objects.all().iterator():
        response_hours, resolution_hours = sla_hours[ticket.priority]
        ticket.first_response_due_at = ticket.created_at + timedelta(hours=response_hours)
        ticket.resolution_due_at = ticket.created_at + timedelta(hours=resolution_hours)
        ticket.first_response_at = (
            Comment.objects.filter(
                ticket_id=ticket.pk,
                author__role__in=('technician', 'admin'),
            )
            .order_by('created_at')
            .values_list('created_at', flat=True)
            .first()
        )
        ticket.save(update_fields=['first_response_due_at', 'resolution_due_at', 'first_response_at'])


